from common import *
import subprocess

if __name__=='__main__':
    register_adapter(__file__)
    first='old-s3000-r1-original'
    while True:
        state=read(STATE)
        current=next(j for j in state['jobs'] if j['job_id']==first)
        if current['status']!='running':break
        try:os.kill(current['pid'],0)
        except ProcessLookupError:raise RuntimeError('first fit disappeared without receipt')
        time.sleep(10)
    if current['status']!='succeeded':raise RuntimeError('first fit failed; inspect before continuing')
    for label,repeat in [('new',1),('old',2),('new',2)]:
        log=TMP/f'{label}-s3000-r{repeat}.log'
        with log.open('w') as f:
            result=subprocess.run([sys.executable,'-u',str(TMP/'fit.py'),label,'3000',str(repeat)],stdout=f,stderr=subprocess.STDOUT,cwd=ROOT)
        if result.returncode:raise RuntimeError(f'{label} r{repeat} failed; see {log}')
    subprocess.run([sys.executable,str(TMP/'compare.py')],cwd=ROOT,check=True)
